class axi_transaction extends uvm_sequence_item;

    typedef enum bit {OP_WRITE, OP_READ} op_e;

    rand op_e             op;
    rand bit [3:0]        id;
    rand bit [31:0]       addr;
    rand bit [7:0]        len;     // burst length minus 1
    rand bit [2:0]        size;    // 2^size bytes per beat
    rand bit [1:0]        burst;   // 00=FIXED, 01=INCR, 10=WRAP, 11=RSVD
    rand bit [31:0]       wdata[]; // dynamic array, len+1 entries
    rand bit [3:0]        wstrb[]; // matching strobes (DATA_WIDTH/8 = 4 bits)

    // Captured outputs (for monitor / scoreboard)
    bit [1:0]             resp;
    bit [31:0]            rdata[];

    // Allow injection of an illegal reserved burst encoding (BURST_RSVD = 2'b11)
    rand bit              inject_rsvd_burst;

    `uvm_object_utils_begin(axi_transaction)
        `uvm_field_enum(op_e, op,         UVM_ALL_ON)
        `uvm_field_int (id,               UVM_ALL_ON)
        `uvm_field_int (addr,             UVM_ALL_ON)
        `uvm_field_int (len,              UVM_ALL_ON)
        `uvm_field_int (size,             UVM_ALL_ON)
        `uvm_field_int (burst,            UVM_ALL_ON)
        `uvm_field_array_int(wdata,       UVM_ALL_ON)
        `uvm_field_array_int(wstrb,       UVM_ALL_ON)
        `uvm_field_int (resp,             UVM_ALL_ON)
        `uvm_field_array_int(rdata,       UVM_ALL_ON)
    `uvm_object_utils_end

    function new(string name = "axi_transaction");
        super.new(name);
    endfunction

    // ── Constraints ──────────────────────────────────────────
    constraint c_size  { size  inside {3'b000, 3'b001, 3'b010}; } // 1B, 2B, 4B
    constraint c_burst {
        if (!inject_rsvd_burst)
            burst inside {2'b01, 2'b10}; // INCR or WRAP
        else
            burst == 2'b11;              // Reserved (illegal)
    }
    constraint c_inject_default { soft inject_rsvd_burst == 1'b0; }

    // Keep length sane (1..16 beats) and align WRAP lengths to 2/4/8/16
    constraint c_len {
        if (burst == 2'b10) // WRAP
            len inside {1, 3, 7, 15};   // beats = 2,4,8,16
        else
            len inside {[0:15]};
    }

    // Keep address inside the modeled MEM_DEPTH=256 words = 1024 bytes
    constraint c_addr {
        addr < 32'h0000_03F0;          // leave headroom for bursts
        // Align starting address to size for WRAP (DUT requires this)
        if (burst == 2'b10)
            (addr & ((1 << size) - 1)) == 0;
    }

    // wdata/wstrb sized to len+1
    constraint c_payload_size {
        wdata.size() == len + 1;
        wstrb.size() == len + 1;
    }

    // Strobes: full strobes by default (WSTRB = 4'hF) for simplicity
    constraint c_wstrb_full {
        foreach (wstrb[i]) wstrb[i] == 4'hF;
    }

