class axi_driver extends uvm_driver #(axi_transaction);
    `uvm_component_utils(axi_driver)

    virtual axi_if axi_vif;

    function new(string name, uvm_component parent);
        super.new(name, parent);
    endfunction

    function void build_phase(uvm_phase phase);
        super.build_phase(phase);
        if (!uvm_config_db#(virtual axi_if)::get(this, "", "axi_vif", axi_vif))
            `uvm_fatal("NOVIF", "Virtual interface not set for axi_driver")
    endfunction

    task run_phase(uvm_phase phase);
        // Initialize all manager-driven outputs to safe defaults
        axi_vif.AWVALID <= 1'b0;
        axi_vif.AWID    <= '0;
        axi_vif.AWADDR  <= '0;
        axi_vif.AWLEN   <= '0;
        axi_vif.AWSIZE  <= '0;
        axi_vif.AWBURST <= '0;
        axi_vif.WVALID  <= 1'b0;
        axi_vif.WDATA   <= '0;
        axi_vif.WSTRB   <= '0;
        axi_vif.WLAST   <= 1'b0;
        axi_vif.BREADY  <= 1'b0;
        axi_vif.ARVALID <= 1'b0;
        axi_vif.ARID    <= '0;
        axi_vif.ARADDR  <= '0;
        axi_vif.ARLEN   <= '0;
        axi_vif.ARSIZE  <= '0;
        axi_vif.ARBURST <= '0;
        axi_vif.RREADY  <= 1'b0;

        // Wait for reset to deassert before sending stimulus
        @(posedge axi_vif.ARESETn);
        @(posedge axi_vif.ACLK);

        forever begin
            axi_transaction tr;
            seq_item_port.get_next_item(tr);
            if (tr.op == axi_transaction::OP_WRITE)
                drive_write(tr);
            else
                drive_read(tr);
            seq_item_port.item_done();
        end
    endtask

    // ── Drive a complete write transaction ────────────────────
    task drive_write(axi_transaction tr);
        // 1. AW handshake
        @(posedge axi_vif.ACLK);
        axi_vif.AWVALID <= 1'b1;
        axi_vif.AWID    <= tr.id;
        axi_vif.AWADDR  <= tr.addr;
        axi_vif.AWLEN   <= tr.len;
        axi_vif.AWSIZE  <= tr.size;
        axi_vif.AWBURST <= tr.burst;

        do @(posedge axi_vif.ACLK);
        while (!axi_vif.AWREADY);
        axi_vif.AWVALID <= 1'b0;

        // 2. W beats
        for (int i = 0; i <= tr.len; i++) begin
            axi_vif.WVALID <= 1'b1;
            axi_vif.WDATA  <= tr.wdata[i];
            axi_vif.WSTRB  <= tr.wstrb[i];
            axi_vif.WLAST  <= (i == tr.len);

            do @(posedge axi_vif.ACLK);
            while (!axi_vif.WREADY);
        end
        axi_vif.WVALID <= 1'b0;
        axi_vif.WLAST  <= 1'b0;

        // 3. B handshake
        axi_vif.BREADY <= 1'b1;
        do @(posedge axi_vif.ACLK);
        while (!axi_vif.BVALID);
        tr.resp = axi_vif.BRESP;
        axi_vif.BREADY <= 1'b0;
    endtask

    // ── Drive a complete read transaction ─────────────────────
    task drive_read(axi_transaction tr);
        int beat_idx;

        // 1. AR handshake
        @(posedge axi_vif.ACLK);
        axi_vif.ARVALID <= 1'b1;
        axi_vif.ARID    <= tr.id;
        axi_vif.ARADDR  <= tr.addr;
        axi_vif.ARLEN   <= tr.len;
        axi_vif.ARSIZE  <= tr.size;
        axi_vif.ARBURST <= tr.burst;

        do @(posedge axi_vif.ACLK);
        while (!axi_vif.ARREADY);
        axi_vif.ARVALID <= 1'b0;

        // 2. R beats
        tr.rdata = new[tr.len + 1];
        axi_vif.RREADY <= 1'b1;
        beat_idx = 0;
        forever begin
            do @(posedge axi_vif.ACLK);
            while (!axi_vif.RVALID);
            tr.rdata[beat_idx] = axi_vif.RDATA;
            tr.resp            = axi_vif.RRESP;
            if (axi_vif.RLAST) break;
            beat_idx++;
        end
        axi_vif.RREADY <= 1'b0;
    endtask
endclass

// ════════════════════════════════════════════════════════════
// Monitor — observes complete write or read transactions
// ════════════════════════════════════════════════════════════

class axi_monitor extends uvm_monitor;
    `uvm_component_utils(axi_monitor)

    virtual axi_if axi_vif;
    uvm_analysis_port #(axi_transaction) ap;

    function new(string name, uvm_component parent);
        super.new(name, parent);
        ap = new("ap", this);
    endfunction

    function void build_phase(uvm_phase phase);
        super.build_phase(phase);
        if (!uvm_config_db#(virtual axi_if)::get(this, "", "axi_vif", axi_vif))
            `uvm_fatal("NOVIF", "Virtual interface not set for axi_monitor")
    endfunction

    task run_phase(uvm_phase phase);
        fork
            monitor_writes();
            monitor_reads();
        join_none
    endtask

    // ── Monitor write channel ──────────────────────────────────
    task monitor_writes();
        forever begin
            axi_transaction tr;
            int idx;

            // Wait for AW handshake
            do @(posedge axi_vif.ACLK);
            while (!(axi_vif.AWVALID && axi_vif.AWREADY));

            tr = axi_transaction::type_id::create("tr_wr");
            tr.op    = axi_transaction::OP_WRITE;
            tr.id    = axi_vif.AWID;
            tr.addr  = axi_vif.AWADDR;
            tr.len   = axi_vif.AWLEN;
            tr.size  = axi_vif.AWSIZE;
            tr.burst = axi_vif.AWBURST;
            tr.wdata = new[tr.len + 1];
            tr.wstrb = new[tr.len + 1];

            // Capture write data beats
            idx = 0;
            forever begin
                do @(posedge axi_vif.ACLK);
                while (!(axi_vif.WVALID && axi_vif.WREADY));
                tr.wdata[idx] = axi_vif.WDATA;
                tr.wstrb[idx] = axi_vif.WSTRB;
                if (axi_vif.WLAST) break;
                idx++;
            end

            // Capture B response
            do @(posedge axi_vif.ACLK);
            while (!(axi_vif.BVALID && axi_vif.BREADY));
            tr.resp = axi_vif.BRESP;

            ap.write(tr);
        end
    endtask

    // ── Monitor read channel ───────────────────────────────────
    task monitor_reads();
        forever begin
            axi_transaction tr;
            int idx;

            do @(posedge axi_vif.ACLK);
            while (!(axi_vif.ARVALID && axi_vif.ARREADY));

            tr = axi_transaction::type_id::create("tr_rd");
            tr.op    = axi_transaction::OP_READ;
            tr.id    = axi_vif.ARID;
            tr.addr  = axi_vif.ARADDR;
            tr.len   = axi_vif.ARLEN;
            tr.size  = axi_vif.ARSIZE;
            tr.burst = axi_vif.ARBURST;
            tr.rdata = new[tr.len + 1];

            // Capture read data beats
            idx = 0;
            forever begin
                do @(posedge axi_vif.ACLK);
                while (!(axi_vif.RVALID && axi_vif.RREADY));
                tr.rdata[idx] = axi_vif.RDATA;
                tr.resp       = axi_vif.RRESP;
                if (axi_vif.RLAST) break;
                idx++;
            end

            ap.write(tr);
        end
    endtask
endclass

// ════════════════════════════════════════════════════════════
// Scoreboard — simple memory model + ID/response check
// ════════════════════════════════════════════════════════════

class axi_scoreboard extends uvm_scoreboard;
    `uvm_component_utils(axi_scoreboard)

    uvm_analysis_imp #(axi_transaction, axi_scoreboard) ap_imp;

    // Reference memory model: 256 words of 32 bits, byte addressable
    bit [7:0] ref_mem [bit[31:0]];

    // Statistics
    int unsigned n_writes      = 0;
    int unsigned n_reads       = 0;
    int unsigned n_resp_okay   = 0;
    int unsigned n_resp_slverr = 0;
    int unsigned n_data_pass   = 0;
    int unsigned n_data_fail   = 0;
    int unsigned n_resp_fail   = 0;

    function new(string name, uvm_component parent);
        super.new(name, parent);
        ap_imp = new("ap_imp", this);
    endfunction

    function void build_phase(uvm_phase phase);
        super.build_phase(phase);
        `uvm_info("SCB", "Scoreboard built and ready", UVM_LOW)
    endfunction

    // Convenience: is this transaction expected to error?
    function bit expect_slverr(axi_transaction tr);
        return (tr.burst == 2'b11);  // Reserved burst
    endfunction

    virtual function void write(axi_transaction tr);
        bit expected_err = (tr.burst == 2'b11);

        // Track response statistics
        if (tr.resp == 2'b00)      n_resp_okay++;
        else if (tr.resp == 2'b10) n_resp_slverr++;

        // Response correctness check
        if (expected_err && tr.resp != 2'b10) begin
            n_resp_fail++;
            `uvm_error("SCB_FAIL",
                $sformatf("Expected SLVERR for reserved burst, got resp=%0b (op=%s id=%0h)",
                          tr.resp, tr.op.name(), tr.id))
        end
        else if (!expected_err && tr.resp != 2'b00) begin
            n_resp_fail++;
            `uvm_error("SCB_FAIL",
                $sformatf("Unexpected error response: resp=%0b (op=%s id=%0h addr=%0h)",
                          tr.resp, tr.op.name(), tr.id, tr.addr))
        end

        // Skip data checking on error transactions
        if (expected_err) begin
            if (tr.op == axi_transaction::OP_WRITE) n_writes++;
            else                                    n_reads++;
            `uvm_info("SCB",
                $sformatf("Reserved-burst %s: id=%0h resp=%0b (expected SLVERR)",
                          tr.op.name(), tr.id, tr.resp), UVM_HIGH)
            return;
        end

        // Process write: update reference memory
        if (tr.op == axi_transaction::OP_WRITE) begin
            update_ref_mem(tr);
            n_writes++;
            `uvm_info("SCB_PASS",
                $sformatf("WRITE id=%0h addr=%0h len=%0d resp=OKAY -> ref mem updated",
                          tr.id, tr.addr, tr.len + 1), UVM_HIGH)
        end
        // Process read: compare against reference memory
        else begin
            check_read(tr);
            n_reads++;
        end
    endfunction

    // Update reference memory based on a successful write transaction
    function void update_ref_mem(axi_transaction tr);
        bit [31:0] cur_addr = tr.addr;
        bit [31:0] start_addr = tr.addr;
        int unsigned size_bytes = (1 << tr.size);
        int unsigned container_bytes;
        bit [31:0] wrap_lo, wrap_hi;

        if (tr.burst == 2'b10) begin
            container_bytes = size_bytes * (tr.len + 1);
            wrap_lo = start_addr - (start_addr % container_bytes);
            wrap_hi = wrap_lo + container_bytes;
        end

        for (int beat = 0; beat <= tr.len; beat++) begin
            bit [31:0] beat_addr;
            int unsigned lower_lane;
            // Compute address per AXI spec
            if (beat == 0) begin
                beat_addr = start_addr;
            end else begin
                bit [31:0] aligned;
                aligned = start_addr & ~(size_bytes - 1);
                if (beat == 1 && (start_addr & (size_bytes - 1)))
                    cur_addr = aligned + size_bytes;
                else
                    cur_addr = cur_addr + size_bytes;
                if (tr.burst == 2'b10 && cur_addr >= wrap_hi)
                    cur_addr = wrap_lo;
                beat_addr = cur_addr;
            end

            // Apply WSTRB byte-by-byte starting from the lane indicated by addr
            lower_lane = beat_addr % 4;  // DATA_BYTES = 4
            for (int b = 0; b < 4; b++) begin
                if (tr.wstrb[beat][b]) begin
                    bit [31:0] byte_addr;
                    byte_addr = (beat_addr & ~32'h3) + b;
                    ref_mem[byte_addr] = tr.wdata[beat][8*b +: 8];
                end
            end

            if (beat == 0) cur_addr = beat_addr;
        end
    endfunction

    // Compare DUT read data against reference memory
    function void check_read(axi_transaction tr);
        bit [31:0] cur_addr = tr.addr;
        bit [31:0] start_addr = tr.addr;
        int unsigned size_bytes = (1 << tr.size);
        int unsigned container_bytes;
        bit [31:0] wrap_lo, wrap_hi;
        bit any_fail = 0;

        if (tr.burst == 2'b10) begin
            container_bytes = size_bytes * (tr.len + 1);
            wrap_lo = start_addr - (start_addr % container_bytes);
            wrap_hi = wrap_lo + container_bytes;
        end

        for (int beat = 0; beat <= tr.len; beat++) begin
            bit [31:0] beat_addr;
            int unsigned lower_lane, upper_lane;
            bit aligned_b;

            if (beat == 0) begin
                beat_addr = start_addr;
            end else begin
                bit [31:0] aligned;
                aligned = start_addr & ~(size_bytes - 1);
                if (beat == 1 && (start_addr & (size_bytes - 1)))
                    cur_addr = aligned + size_bytes;
                else
                    cur_addr = cur_addr + size_bytes;
                if (tr.burst == 2'b10 && cur_addr >= wrap_hi)
                    cur_addr = wrap_lo;
                beat_addr = cur_addr;
            end

            // Compare each active byte lane
            aligned_b = ((beat_addr & (size_bytes - 1)) == 0);
            lower_lane = beat_addr % 4;
            upper_lane = aligned_b ? lower_lane + size_bytes - 1
                                   : ((beat_addr & ~(size_bytes - 1)) + size_bytes - 1) % 4;

            for (int lane = lower_lane; lane <= upper_lane; lane++) begin
                bit [31:0] byte_addr;
                bit [7:0]  exp_byte;
                bit [7:0]  got_byte;
                byte_addr = (beat_addr & ~32'h3) + lane - lower_lane + (beat_addr % 4);
                // Simpler: source byte = (beat_addr + (lane - lower_lane))
                byte_addr = beat_addr + (lane - lower_lane);
                exp_byte  = ref_mem.exists(byte_addr) ? ref_mem[byte_addr] : 8'h00;
                got_byte  = tr.rdata[beat][8*lane +: 8];

                if (exp_byte !== got_byte) begin
                    any_fail = 1;
                    n_data_fail++;
                    `uvm_error("SCB_FAIL",
                        $sformatf("READ data mismatch: id=%0h beat=%0d byte_addr=%0h lane=%0d exp=%02h got=%02h",
                                  tr.id, beat, byte_addr, lane, exp_byte, got_byte))
                end
            end

            if (beat == 0) cur_addr = beat_addr;
        end

        if (!any_fail) begin
            n_data_pass++;
            `uvm_info("SCB_PASS",
                $sformatf("READ id=%0h addr=%0h len=%0d -> data matches reference",
                          tr.id, tr.addr, tr.len + 1), UVM_HIGH)
        end
    endfunction

    function void report_phase(uvm_phase phase);
        super.report_phase(phase);
        `uvm_info("SCB_SUMMARY",
            $sformatf("\n========== SCOREBOARD SUMMARY ==========\n  Write transactions : %0d\n  Read transactions  : %0d\n  Resp OKAY          : %0d\n  Resp SLVERR        : %0d\n  Resp mismatches    : %0d\n  Read data passes   : %0d\n  Read data failures : %0d\n  Result             : %s\n========================================",
                n_writes, n_reads, n_resp_okay, n_resp_slverr,
                n_resp_fail, n_data_pass, n_data_fail,
                ((n_resp_fail == 0) && (n_data_fail == 0) && (n_writes + n_reads > 0))
                    ? "*** PASS ***"
                    : ((n_writes + n_reads == 0)
                        ? "*** NO TRANSACTIONS — CHECK WIRING ***"
                        : "*** FAIL ***")),
            UVM_LOW)
    endfunction
endclass

// ════════════════════════════════════════════════════════════
// Functional Coverage
// ════════════════════════════════════════════════════════════

class axi_coverage extends uvm_subscriber #(axi_transaction);
    `uvm_component_utils(axi_coverage)

    axi_transaction tr;
    int unsigned n_samples = 0;

    covergroup cg_axi;
        option.per_instance = 1;
        option.name         = "cg_axi";

        cp_op: coverpoint tr.op {
            bins write_op = {axi_transaction::OP_WRITE};
            bins read_op  = {axi_transaction::OP_READ};
        }

        cp_burst: coverpoint tr.burst {
            bins incr     = {2'b01};
            bins wrap     = {2'b10};
            bins reserved = {2'b11};
            ignore_bins fixed_unused = {2'b00};
        }

        cp_size: coverpoint tr.size {
            bins size_1B = {3'b000};
            bins size_2B = {3'b001};
            bins size_4B = {3'b010};
        }

        cp_len: coverpoint tr.len {
            bins single  = {0};
            bins short_b = {[1:3]};
            bins medium_b  = {[4:7]};
            bins long_b  = {[8:15]};
        }

        cp_resp: coverpoint tr.resp {
            bins okay   = {2'b00};
            bins slverr = {2'b10};
        }

        cx_op_burst:  cross cp_op, cp_burst;
        cx_size_burst: cross cp_size, cp_burst {
            ignore_bins ig_rsvd_size = binsof(cp_burst.reserved);
        }
        cx_op_resp:   cross cp_op, cp_resp;
    endgroup

    function new(string name, uvm_component parent);
        super.new(name, parent);
        cg_axi = new();
    endfunction

    function void build_phase(uvm_phase phase);
        super.build_phase(phase);
        `uvm_info("COV", "Coverage collector built and ready", UVM_LOW)
    endfunction

    virtual function void write(axi_transaction t);
        tr = t;
        cg_axi.sample();
        n_samples++;
    endfunction

    function void report_phase(uvm_phase phase);
        super.report_phase(phase);
        `uvm_info("COV_SUMMARY",
            $sformatf("\n========== COVERAGE SUMMARY ==========\n  Samples taken   : %0d\n  cp_op           : %0.2f%%\n  cp_burst        : %0.2f%%\n  cp_size         : %0.2f%%\n  cp_len          : %0.2f%%\n  cp_resp         : %0.2f%%\n  cx_op_burst     : %0.2f%%\n  cx_size_burst   : %0.2f%%\n  cx_op_resp      : %0.2f%%\n  Overall cg_axi  : %0.2f%%\n======================================",
                n_samples,
                cg_axi.cp_op.get_coverage(),
                cg_axi.cp_burst.get_coverage(),
                cg_axi.cp_size.get_coverage(),
                cg_axi.cp_len.get_coverage(),
                cg_axi.cp_resp.get_coverage(),
                cg_axi.cx_op_burst.get_coverage(),
                cg_axi.cx_size_burst.get_coverage(),
                cg_axi.cx_op_resp.get_coverage(),
                cg_axi.get_coverage()),
            UVM_LOW)
    endfunction
endclass

// ════════════════════════════════════════════════════════════
// Agent
// ════════════════════════════════════════════════════════════

class axi_agent extends uvm_agent;
    `uvm_component_utils(axi_agent)

    axi_driver    driver;
    axi_monitor   monitor;
    axi_sequencer sequencer;

    function new(string name, uvm_component parent);
        super.new(name, parent);
    endfunction

    function void build_phase(uvm_phase phase);
        super.build_phase(phase);
        monitor = axi_monitor::type_id::create("monitor", this);
        if (get_is_active() == UVM_ACTIVE) begin
            driver    = axi_driver::type_id::create("driver", this);
            sequencer = axi_sequencer::type_id::create("sequencer", this);
        end
    endfunction

    function void connect_phase(uvm_phase phase);
        super.connect_phase(phase);
        if (get_is_active() == UVM_ACTIVE)
            driver.seq_item_port.connect(sequencer.seq_item_export);
    endfunction
endclass

// ════════════════════════════════════════════════════════════
// Environment
// ════════════════════════════════════════════════════════════

class axi_env extends uvm_env;
    `uvm_component_utils(axi_env)

    axi_agent      agent;
    axi_scoreboard scoreboard;
    axi_coverage   coverage;

    function new(string name, uvm_component parent);
        super.new(name, parent);
    endfunction

    function void build_phase(uvm_phase phase);
        super.build_phase(phase);
        agent      = axi_agent::type_id::create("agent", this);
        scoreboard = axi_scoreboard::type_id::create("scoreboard", this);
        coverage   = axi_coverage::type_id::create("coverage", this);
    endfunction

    function void connect_phase(uvm_phase phase);
        super.connect_phase(phase);
        agent.monitor.ap.connect(scoreboard.ap_imp);
        agent.monitor.ap.connect(coverage.analysis_export);
    endfunction
endclass

// ════════════════════════════════════════════════════════════
// Test
// ════════════════════════════════════════════════════════════

class axi_test extends uvm_test;
    `uvm_component_utils(axi_test)

    axi_env env;

    function new(string name = "axi_test", uvm_component parent = null);
        super.new(name, parent);
    endfunction

    function void build_phase(uvm_phase phase);
        super.build_phase(phase);
        env = axi_env::type_id::create("env", this);
    endfunction

    task run_phase(uvm_phase phase);
        axi_main_seq main_seq;
        phase.raise_objection(this);

        main_seq = axi_main_seq::type_id::create("main_seq");
        main_seq.start(env.agent.sequencer);

        // Drain any in-flight responses
        #200;
        phase.drop_objection(this);
    endtask
endclass

// ════════════════════════════════════════════════════════════
// Top-Level Module
// ════════════════════════════════════════════════════════════

module tb_top;
    `include "uvm_macros.svh"
    import uvm_pkg::*;

    logic ACLK;
    logic ARESETn;

    // Interface
    axi_if axi_interface(.ACLK(ACLK));

    // Wire ARESETn into the interface
    assign axi_interface.ARESETn = ARESETn;

    // DUT
    axi_mem #(
        .ADDR_WIDTH(32),
        .DATA_WIDTH(32),
        .ID_WIDTH(4),
        .MEM_DEPTH(256)
    ) dut (
        .ACLK    (axi_interface.ACLK),
        .ARESETn (axi_interface.ARESETn),
        .AWID    (axi_interface.AWID),
        .AWADDR  (axi_interface.AWADDR),
        .AWLEN   (axi_interface.AWLEN),
        .AWSIZE  (axi_interface.AWSIZE),
        .AWBURST (axi_interface.AWBURST),
        .AWVALID (axi_interface.AWVALID),
        .AWREADY (axi_interface.AWREADY),
        .WDATA   (axi_interface.WDATA),
        .WSTRB   (axi_interface.WSTRB),
        .WLAST   (axi_interface.WLAST),
        .WVALID  (axi_interface.WVALID),
        .WREADY  (axi_interface.WREADY),
        .BID     (axi_interface.BID),
        .BRESP   (axi_interface.BRESP),
        .BVALID  (axi_interface.BVALID),
        .BREADY  (axi_interface.BREADY),
        .ARID    (axi_interface.ARID),
        .ARADDR  (axi_interface.ARADDR),
        .ARLEN   (axi_interface.ARLEN),
        .ARSIZE  (axi_interface.ARSIZE),
        .ARBURST (axi_interface.ARBURST),
        .ARVALID (axi_interface.ARVALID),
        .ARREADY (axi_interface.ARREADY),
        .RID     (axi_interface.RID),
        .RDATA   (axi_interface.RDATA),
        .RRESP   (axi_interface.RRESP),
        .RLAST   (axi_interface.RLAST),
        .RVALID  (axi_interface.RVALID),
        .RREADY  (axi_interface.RREADY)
    );

    // Clock
    initial begin
        ACLK = 1'b0;
        forever #5 ACLK = ~ACLK;
    end

    // Reset
    initial begin
        ARESETn = 1'b0;
        repeat (5) @(posedge ACLK);
        ARESETn = 1'b1;
    end

    // Publish virtual interface and start UVM
    initial begin
        uvm_config_db#(virtual axi_if)::set(null, "*", "axi_vif", axi_interface);
        run_test("axi_test");
    end

    // Optional waveform dump
    initial begin
        $dumpfile("dump.vcd");
        $dumpvars(0, tb_top);
    end
endmodule
